import express from "express";
import cors from "cors";
import path from "path";
import dotenv from "dotenv";
import mysql from "mysql2/promise";
import { drizzle } from "drizzle-orm/mysql2";
import { eq, and } from "drizzle-orm";
import fs from "fs";
import jwt from "jsonwebtoken";
import bcrypt from "bcryptjs";
import multer from "multer";
import { createServer as createViteServer } from "vite";
import * as schema from "./src/db/schema";

dotenv.config();

const app = express();
app.use(cors());
app.use(express.json({ limit: '50mb' }));
const PORT = 3000;

// Setup static uploads directory
const uploadsDir = path.join(process.cwd(), "uploads");
if (!fs.existsSync(uploadsDir)) {
  fs.mkdirSync(uploadsDir);
}
app.use("/uploads", express.static(uploadsDir));

const upload = multer({
  dest: uploadsDir,
  limits: { fileSize: 10 * 1024 * 1024 } // 10MB limit
});

app.post("/api/upload", upload.single("image"), (req, res) => {
  if (!req.file) return res.status(400).json({ error: "No file uploaded" });
  
  // You can return the URL to the saved file
  const fileUrl = `/uploads/${req.file.filename}`;
  res.json({ url: fileUrl });
});

// Connect to MySQL using env credentials
let sslConfig: any = { rejectUnauthorized: false };
if (process.env.MYSQL_CA_CERT) {
  try {
    if (process.env.MYSQL_CA_CERT.includes("BEGIN CERTIFICATE")) {
      sslConfig = { ca: process.env.MYSQL_CA_CERT, rejectUnauthorized: true };
    } else if (fs.existsSync(process.env.MYSQL_CA_CERT)) {
      sslConfig = { ca: fs.readFileSync(process.env.MYSQL_CA_CERT, "utf8"), rejectUnauthorized: true };
    }
  } catch (e) {
    console.error("Failed to parse MYSQL_CA_CERT", e);
  }
}

const pool = mysql.createPool({
  host: process.env.MYSQL_HOST,
  port: parseInt(process.env.MYSQL_PORT || "26535"),
  user: process.env.MYSQL_USER,
  password: process.env.MYSQL_PASSWORD,
  database: process.env.MYSQL_DATABASE,
  ssl: sslConfig,
});

const db = drizzle(pool, { schema, mode: "default" });

(async () => {
  try {
    const [cols] = await pool.query("SHOW COLUMNS FROM properties LIKE 'views'");
    if ((cols as any[]).length === 0) {
      await pool.query("ALTER TABLE properties ADD COLUMN views INT DEFAULT 0");
      console.log("Added views column to properties table");
    }
    const [userCols] = await pool.query("SHOW COLUMNS FROM users LIKE 'whatsapp'");
    if ((userCols as any[]).length === 0) {
      await pool.query("ALTER TABLE users ADD COLUMN whatsapp VARCHAR(100)");
      console.log("Added whatsapp column to users table");
    }
  } catch(e) {
    console.error("Schema evolution error:", e);
  }
})();

const JWT_SECRET = process.env.JWT_SECRET || "super-secret-jwt-key";

// Auth Endpoint
app.post("/api/auth/login", async (req, res) => {
  const { email, password } = req.body;
  if (!email || !password) return res.status(400).json({ error: "Missing fields" });

  try {
    const result: any = await db.query.users.findFirst({ where: (u, { eq }) => eq(u.email, email) });
    if (!result) return res.status(401).json({ error: "Invalid credentials" });

    // For plain passwords or bcrypt
    const pass = result.passwordHash || result.password;
    const isValid = await bcrypt.compare(password, pass).catch(() => password === pass);
    if (!isValid && password !== pass) return res.status(401).json({ error: "Invalid credentials" });

    const token = jwt.sign({ id: result.id, role: result.role, email: result.email }, JWT_SECRET);
    res.json({ token, user: { id: result.id, email: result.email, role: result.role, fullName: result.fullName || result.name } });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

const collectionsMap: Record<string, any> = {
  users: (schema as any).users,
  properties: (schema as any).properties,
  tenants: (schema as any).tenants,
  contracts: (schema as any).contracts,
  payments: (schema as any).payments,
  discounts: (schema as any).discounts,
  audit_logs: (schema as any).auditLogs
};

app.post('/api/db/getDocs', async (req, res) => {
   const { path, constraints } = req.body;
   const table = collectionsMap[path];
   if (!table) return res.status(404).json({ error: 'Table not found' });
   
   let conditions = [];
   for (const c of (constraints || [])) {
       if (c.type === 'where') {
           const col = table[c.field];
           if (!col) {
               console.error(`Invalid field: ${c.field} on table ${path}`);
               return res.status(400).json({ error: `Invalid field: ${c.field}` });
           }
           if (c.op === '==') conditions.push(eq(col, c.value));
       }
   }
   
   try {
       const results = await db.select().from(table).where(conditions.length > 0 ? and(...conditions) : undefined);
       res.json(results);
   } catch(e: any) {
       console.error("error in getDocs", e);
       res.status(500).json({ error: e.message });
   }
});

app.post('/api/db/getDoc', async (req, res) => {
    const { path, id } = req.body;
    const table = collectionsMap[path];
    if (!table) return res.status(404).json({ error: 'Table not found' });
    try {
        const resultList = await db.select().from(table).where(eq(table.id, id)).limit(1);
        const result = resultList.length > 0 ? resultList[0] : null;
        res.json(result || null);
    } catch(e: any) {
        res.status(500).json({ error: e.message });
    }
});

const cleanDataForDB = (data: any) => {
    const cleanData = { ...data };
    for (const [k, v] of Object.entries(cleanData)) {
        if (v && typeof v === 'object' && 'seconds' in v) {
            cleanData[k] = new Date((v as any).seconds * 1000);
        } else if (v && typeof v === 'string' && (k === 'createdAt' || k === 'updatedAt' || k === 'timestamp')) {
            cleanData[k] = new Date(v);
        }
    }
    return cleanData;
};

app.post('/api/db/setDoc', async (req, res) => {
    const { ref, data, options } = req.body;
    const table = collectionsMap[ref.path];
    if (!table) return res.status(404).json({ error: 'Table not found' });
    
    try {
        const id = ref.id;
        const existsList = await db.select().from(table).where(eq(table.id, id)).limit(1);
        const exists = existsList.length > 0;
        
        const cleanData = cleanDataForDB(data);
        cleanData.id = id;

        if (exists) {
            if (options?.merge) {
                await db.update(table).set(cleanData).where(eq(table.id, id));
            } else {
                await db.delete(table).where(eq(table.id, id));
                await db.insert(table).values(cleanData);
            }
        } else {
            await db.insert(table).values(cleanData);
        }
        res.json({ success: true, id });
    } catch(e: any) {
        console.error("setDoc error:", e);
        res.status(500).json({ error: e.message });
    }
});

app.post('/api/db/updateDoc', async (req, res) => {
    const { ref, data } = req.body;
    const table = collectionsMap[ref.path];
    if (!table) return res.status(404).json({ error: 'Table not found' });
    
    try {
        const cleanData = cleanDataForDB(data);
        await db.update(table).set(cleanData).where(eq(table.id, ref.id));
        res.json({ success: true });
    } catch(e: any) {
        res.status(500).json({ error: e.message });
    }
});

app.post('/api/db/deleteDoc', async (req, res) => {
    const { ref } = req.body;
    const table = collectionsMap[ref.path];
    if (!table) return res.status(404).json({ error: 'Table not found' });
    try {
        await db.delete(table).where(eq(table.id, ref.id));
        res.json({ success: true });
    } catch(e: any) {
        res.status(500).json({ error: e.message });
    }
});

app.post('/api/db/batch', async (req, res) => {
    const { operations } = req.body;
    try {
        await db.transaction(async (tx) => {
            for (const op of operations) {
                const table = collectionsMap[op.ref.path];
                if (!table) continue;
                
                const cleanData = cleanDataForDB(op.data || {});
                
                if (op.type === 'set') {
                    cleanData.id = op.ref.id;
                    const existsList = await tx.select().from(table).where(eq(table.id, op.ref.id)).limit(1);
                    const exists = existsList.length > 0;
                    if (exists) {
                        if (op.options?.merge) {
                            await tx.update(table).set(cleanData).where(eq(table.id, op.ref.id));
                        } else {
                            await tx.delete(table).where(eq(table.id, op.ref.id));
                            await tx.insert(table).values(cleanData);
                        }
                    } else {
                        await tx.insert(table).values(cleanData);
                    }
                } else if (op.type === 'update') {
                    await tx.update(table).set(cleanData).where(eq(table.id, op.ref.id));
                } else if (op.type === 'delete') {
                    await tx.delete(table).where(eq(table.id, op.ref.id));
                }
            }
        });
        res.json({ success: true });
    } catch(e: any) {
        console.error("batch error", e);
        res.status(500).json({ error: e.message });
    }
});

app.post('/api/db/init', async (req, res) => {
    try {
        const tables = ['audit_logs', 'contracts', 'discounts', 'payments', 'properties', 'tenants', 'users'];
        for (const table of tables) {
            await pool.query(`DROP TABLE IF EXISTS ${table}`);
        }
        
        const migDir = path.join(process.cwd(), 'src/db/migrations');
        const migFile = fs.readdirSync(migDir).find(f => f.endsWith('.sql'));
        if (!migFile) throw new Error("No migration file found.");
        
        const migPath = path.join(migDir, migFile);
        const sql = fs.readFileSync(migPath, 'utf8');
        const statements = sql.split('--> statement-breakpoint').map(s => s.trim()).filter(s => s.length > 0);
        
        for (const stmt of statements) {
            await pool.query(stmt);
        }
        res.json({ success: true, message: "Database re-initialized." });
    } catch(e: any) {
        res.status(500).json({ error: e.message });
    }
});

// Setup Vite for development
async function startServer() {
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", async () => {
    console.log(`Server running on http://localhost:${PORT}`);
    // Basic sanity check connection
    try {
      const connection = await pool.getConnection();
      console.log("Connected to MySQL database!");
      connection.release();
    } catch(e) {
      console.error("Failed to connect to DB at startup:", e);
    }
  });
}

startServer();
