import { mysqlTable, varchar, timestamp, int, json, double, text, boolean, datetime } from "drizzle-orm/mysql-core";

export const users = mysqlTable("users", {
  id: varchar("id", { length: 255 }).primaryKey(),
  email: varchar("email", { length: 255 }).unique(),
  passwordHash: varchar("password_hash", { length: 255 }),
  role: varchar("role", { length: 50 }), // 'OWNER' | 'TENANT'
  name: varchar("full_name", { length: 255 }),
  tenantLinkCode: varchar("tenant_link_code", { length: 100 }),
  portfolioSlug: varchar("portfolio_slug", { length: 100 }),
  phone: varchar("phone", { length: 100 }),
  whatsapp: varchar("whatsapp", { length: 100 }),
  nationalId: varchar("national_id", { length: 100 }),
  profilePicture: text("profile_picture"),
  instagram: varchar("instagram", { length: 255 }),
  facebook: varchar("facebook", { length: 255 }),
  twitter: varchar("twitter", { length: 255 }),
  website: varchar("website", { length: 255 }),
  currency: varchar("currency", { length: 10 }),
  generalBalance: double("general_balance").default(0),
  createdAt: timestamp("created_at").defaultNow(),
});

export const properties = mysqlTable("properties", {
  id: varchar("id", { length: 255 }).primaryKey(),
  customId: varchar("custom_id", { length: 100 }),
  name: varchar("name", { length: 255 }),
  type: varchar("type", { length: 100 }),
  address: text("address"),
  governorate: varchar("governorate", { length: 100 }),
  city: varchar("city", { length: 100 }),
  area: double("area"),
  rooms: int("rooms"),
  unitNumber: varchar("unit_number", { length: 100 }),
  description: text("description"),
  status: varchar("status", { length: 50 }),
  ownerId: varchar("owner_id", { length: 255 }),
  purchasingDetails: json("purchasing_details"),
  estimatedValue: varchar("estimated_value", { length: 100 }),
  features: json("features"),
  currentTenant: varchar("current_tenant", { length: 255 }),
  rentStart: varchar("rent_start", { length: 100 }),
  contractEnd: varchar("contract_end", { length: 100 }),
  rentPrice: double("rent_price"),
  increaseRate: double("increase_rate"),
  deposit: double("deposit"),
  terms: text("terms"),
  mapLink: text("map_link"),
  paymentMethod: varchar("payment_method", { length: 100 }),
  images: json("images"),
  views: int("views").default(0),
  createdAt: timestamp("created_at").defaultNow(),
});

export const tenants = mysqlTable("tenants", {
  id: varchar("id", { length: 255 }).primaryKey(),
  fullName: varchar("full_name", { length: 255 }),
  nationalId: varchar("national_id", { length: 100 }),
  email: varchar("email", { length: 255 }),
  phone: varchar("phone", { length: 100 }),
  whatsapp: varchar("whatsapp", { length: 100 }),
  address: text("address"),
  signature: text("signature"),
  tenantLinkCode: varchar("tenant_link_code", { length: 100 }),
  documents: json("documents"),
  idCardPath: text("id_card_path"),
  notes: text("notes"),
  userId: varchar("user_id", { length: 255 }),
  ownerId: varchar("owner_id", { length: 255 }),
  createdAt: timestamp("created_at").defaultNow(),
});

export const contracts = mysqlTable("contracts", {
  id: varchar("id", { length: 255 }).primaryKey(),
  contractNumber: varchar("contract_number", { length: 100 }),
  propertyId: varchar("property_id", { length: 255 }),
  tenantId: varchar("tenant_id", { length: 255 }),
  startDate: varchar("start_date", { length: 100 }),
  endDate: varchar("end_date", { length: 100 }),
  durationMonths: int("duration_months"),
  monthlyRent: double("monthly_rent"),
  insuranceAmount: double("insurance_amount"),
  annualIncrease: double("annual_increase"),
  rentAmount: double("rent_amount"),
  paymentFrequency: varchar("payment_frequency", { length: 50 }),
  paymentMethod: varchar("payment_method", { length: 100 }),
  lateFee: double("late_fee"),
  status: varchar("status", { length: 50 }), // 'ACTIVE' | 'EXPIRED' | 'CANCELLED'
  details: text("details"),
  additionalTerms: text("additional_terms"),
  renewable: boolean("renewable"),
  pdfPath: text("pdf_path"),
  ownerId: varchar("owner_id", { length: 255 }),
  createdAt: timestamp("created_at").defaultNow(),
});

export const payments = mysqlTable("payments", {
  id: varchar("id", { length: 255 }).primaryKey(),
  contractId: varchar("contract_id", { length: 255 }),
  propertyId: varchar("property_id", { length: 255 }),
  tenantId: varchar("tenant_id", { length: 255 }),
  paymentNumber: varchar("payment_number", { length: 100 }),
  amount: double("amount").default(0),
  paidAmount: double("paid_amount").default(0),
  totalPaid: double("total_paid").default(0),
  discountAmount: double("discount_amount").default(0),
  lateFeeApplied: double("late_fee_applied").default(0),
  dueDate: varchar("due_date", { length: 100 }),
  status: varchar("status", { length: 50 }), // 'PENDING' | 'PAID'
  datePaid: varchar("date_paid", { length: 100 }),
  paymentDate: varchar("payment_date", { length: 100 }),
  method: varchar("method", { length: 50 }),
  type: varchar("type", { length: 50 }),
  notes: text("notes"),
  receiptUrl: text("receipt_url"),
  ownerId: varchar("owner_id", { length: 255 }),
  createdAt: timestamp("created_at").defaultNow(),
});

export const discounts = mysqlTable("discounts", {
  id: varchar("id", { length: 255 }).primaryKey(),
  amount: double("amount"),
  reason: text("reason"),
  date: varchar("date", { length: 100 }),
  ownerId: varchar("owner_id", { length: 255 }),
  createdAt: timestamp("created_at").defaultNow(),
});

export const auditLogs = mysqlTable("audit_logs", {
  id: varchar("id", { length: 255 }).primaryKey(),
  userId: varchar("user_id", { length: 255 }),
  action: varchar("action", { length: 100 }),
  entityType: varchar("entity_type", { length: 100 }),
  entityId: varchar("entity_id", { length: 255 }),
  details: text("details"),
  ownerId: varchar("owner_id", { length: 255 }),
  timestamp: timestamp("timestamp").defaultNow(),
});
